server_config.nginx_example:
server {
  listen 80;
  server_name yourdomain.com;
  root /path/to/3D;
  index index.html;

  location / {
    try_files $uri $uri/ =404;
  }

  # 静态资源缓存控制
  location ~* \.(jpg|jpeg|png|webp|svg|css|js|glb|gltf)$ {
    expires 1y;
    add_header Cache-Control "public, max-age=31536000";
  }

  gzip on;
  gzip_comp_level 5;
  gzip_min_length 256;
  gzip_types text/css application/javascript application/json image/svg+xml;
}
